import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns } from "./_shared";

/**
 * One row per completed bulk import, keyed by `(org_id, import_key)`. Its
 * `issue_ids` is the file-ordered list `IssueService.importIssues` returns on
 * a replay, so a replay never has to re-derive order from the issues table.
 */
export const issueImports = sqliteTable(
  "issue_imports",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    importKey: text("import_key").notNull(),
    issueIds: text("issue_ids").notNull().default("[]"),
    createdAt: text("created_at")
      .notNull()
      .$defaultFn(() => new Date().toISOString()),
  },
  (table) => [
    uniqueIndex("issue_imports_org_key_idx").on(table.orgId, table.importKey),
  ],
);

export type IssueImportRow = typeof issueImports.$inferSelect;

