/**
 * The `(org_id, import_key)` ledger behind `IssueService.importIssues`'s
 * replay guarantee. One row per completed import; a fresh key writes here
 * only after the issues it names already exist.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, parseJsonArray } from "./_mappers";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

export interface IssueImportRecord {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

export async function findImportByKey(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();

  if (!row) return null;

  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

export async function insertImport(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  issueIds: readonly IssueId[],
): Promise<void> {
  getDb()
    .insert(issueImports)
    .values({
      id: newId(),
      orgId,
      projectId,
      importKey,
      issueIds: JSON.stringify(issueIds),
      createdAt: toIsoTimestamp(new Date()),
    })
    .run();
}

