  orgId: OrgId,
  projectId: ProjectId,
  authorId: UserId,
  startNumber: number,
  seeds: readonly ImportedIssueSeed[],
): Promise<readonly Issue[]> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const rows = seeds.map((seed, index) => ({
    id: newId(),
    orgId,
    projectId,
    number: startNumber + index,
    title: seed.title,
    description: seed.description,
    status: seed.status,
    priority: seed.priority,
    authorId,
    assigneeId: seed.assigneeId,
    parentId: null,
    estimate: null,
    dueAt: seed.dueAt,
    startedAt: null,
    completedAt: null,
    createdAt: stamp,
    updatedAt: stamp,
    archivedAt: null,
  }));

  db.insert(issues).values(rows).run();

  const labelRows = rows.flatMap((row, index) =>
    seeds[index]!.labelIds.map((labelId) => ({
