/**
 * Bulk import: every row becomes an issue, in file order, gated by the same
 * checks as `createIssue` plus a rate allowance and a persisted replay key.
 * All or nothing — the checks run before anything is written, and a refused
 * import never consumes its key.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await issueImportRepo.findImportByKey(
    input.orgId,
    input.importKey,
  );
  if (replay !== null) {
    return {
      importKey: input.importKey,
      projectId: replay.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, replay.issueIds),
      replayed: true,
    };
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const assigneeByEmail = await resolveAssigneesByEmail(input.orgId, input.rows);
  const labelIdByName = await resolveLabelsByName(input.orgId, input.rows);

  const seeds: ImportedIssueSeed[] = input.rows.map((row) => ({
    title: row.title,
    description: row.description,
    status: row.status,
    priority: row.priority,
    assigneeId:
      row.assigneeEmail === null
        ? null
        : (assigneeByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
    dueAt: row.dueAt,
    labelIds: [...new Set(row.labels)]
      .map((name) => labelIdByName.get(name))
      .filter((id): id is LabelId => id !== undefined),
  }));

  const startNumber = await issueRepo.nextIssueNumber(
    input.orgId,
    input.projectId,
  );
  const issues = await issueRepo.insertImportedIssues(
    input.orgId,
    input.projectId,
    actor.userId,
    startNumber,
    seeds,
  );

  const issueIds = issues.map((issue) => issue.id);
  await issueImportRepo.insertImport(
    input.orgId,
    input.projectId,
    input.importKey,
    issueIds,
  );

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

/** Case-insensitive match against the workspace's active members; unknown → unassigned. */
async function resolveAssigneesByEmail(
  orgId: OrgId,
  rows: ImportIssuesInput["rows"],
): Promise<Map<string, Actor["userId"]>> {
  const wanted = new Set(
    rows
      .map((row) => row.assigneeEmail)
      .filter((email): email is string => email !== null)
      .map((email) => email.toLowerCase()),
  );
  if (wanted.size === 0) return new Map();

  const members = await memberRepo.listActiveMemberEmails(orgId);
  const byEmail = new Map<string, Actor["userId"]>();
  for (const member of members) {
    const key = member.email.toLowerCase();
    if (wanted.has(key)) byEmail.set(key, member.userId);
  }
  return byEmail;
}

/** Exact, case-sensitive match against the workspace's labels; missing names are created once. */
async function resolveLabelsByName(
  orgId: OrgId,
  rows: ImportIssuesInput["rows"],
): Promise<Map<string, LabelId>> {
  const names = [...new Set(rows.flatMap((row) => row.labels))];
  if (names.length === 0) return new Map();

  const existing = await labelRepo.findLabelsByNames(orgId, names);
  const byName = new Map(existing.map((label) => [label.name, label.id]));

  for (const name of names) {
    if (byName.has(name)) continue;
    const created = await labelRepo.insertLabel({
      orgId,
      name,
      color: DEFAULT_LABEL_COLOR,
      description: null,
    });
    byName.set(name, created.id);
  }

  return byName;
}

