import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { resetRateLimits } from "@/lib/rate-limit";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as labelRepo from "@/server/repositories/label-repository";
import * as usageService from "@/server/services/usage-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import { NotFoundError } from "@/server/services/_support";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, ProjectId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetRateLimits();
  tenant = await createTenant("importsvc", "growth");
});

afterAll(() => {
  cleanup();
});

function row(overrides: Partial<{ title: string; assigneeEmail: string | null; labels: string[] }> = {}) {
  return {
    title: overrides.title ?? "Imported row",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeEmail: overrides.assigneeEmail ?? null,
    labels: overrides.labels ?? [],
    dueAt: null,
  };
}

describe("scratch: importIssues", () => {
  it("imports rows in order, resolves assignee/labels, numbers after existing issues, emits one event, no issue.created", async () => {
    const created = await issueService.createIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      title: "Existing issue",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
    expect(created.number).toBe(1);

    const seenImported: unknown[] = [];
    const seenCreated: unknown[] = [];
    const offImported = subscribe("issues.imported", (p) => seenImported.push(p));
    const offCreated = subscribe("issue.created", (p) => seenCreated.push(p));

    const result = await issueService.importIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "import-key-001",
      rows: [
        row({ title: "First row", assigneeEmail: `admin@importsvc.test`, labels: ["bug", "urgent-label"] }),
        row({ title: "Second row", assigneeEmail: "nobody@nowhere.test", labels: ["bug"] }),
        row({ title: "Third row" }),
      ],
    });

    offImported();
    offCreated();

    expect(result.replayed).toBe(false);
    expect(result.issues.map((i) => i.title)).toEqual(["First row", "Second row", "Third row"]);
    expect(result.issues.map((i) => i.number)).toEqual([2, 3, 4]);
    expect(result.issues[0]?.assigneeId).toBe(tenant.userIds.admin);
    expect(result.issues[1]?.assigneeId).toBeNull();
    expect(result.issues.every((i) => i.authorId === tenant.actors.member.userId)).toBe(true);
    expect(result.issues.every((i) => i.parentId === null && i.estimate === null)).toBe(true);

    const labels = await labelRepo.listLabels(tenant.org.id);
    const bug = labels.find((l) => l.name === "bug");
    expect(bug).toBeDefined();
    expect(bug?.color).toBe("#94a3b8");
    expect(result.issues[0]?.labelIds).toContain(bug?.id);

    expect(seenCreated).toHaveLength(0);
    expect(seenImported).toHaveLength(1);
    expect(seenImported[0]).toMatchObject({
      projectId: tenant.project.id,
      importKey: "import-key-001",
      issueIds: result.issues.map((i) => i.id),
    });

    // Replay: same key returns same issues, creates nothing new, emits nothing.
    const seenImported2: unknown[] = [];
    const off2 = subscribe("issues.imported", (p) => seenImported2.push(p));
    const replay = await issueService.importIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "import-key-001",
      rows: [row({ title: "Different now" })],
    });
    off2();
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((i) => i.id)).toEqual(result.issues.map((i) => i.id));
    expect(seenImported2).toHaveLength(0);

    // Continuing numbering after import.
    const next = await issueService.createIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      title: "After import",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
    expect(next.number).toBe(5);
  });

  it("refuses tenant scope, not found, archived, permission", async () => {
    const other = await createTenant("importother", "growth");

    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: other.org.id,
        projectId: other.project.id,
        importKey: "cross-tenant-key",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: "01HZZZUNKNOWNPROJECTIDXXX" as ProjectId,
        importKey: "unknown-project-key",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(tenant.actors.viewer, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "viewer-forbidden-key",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const archivedProject = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Archived target",
      slug: "archived-target",
      key: "ARCH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: archivedProject.id,
      archiveIssues: false,
    });
    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: archivedProject.id,
        importKey: "archived-project-key",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses the whole batch at the plan's per-project quota and creates nothing; key stays unused", async () => {
    const quotaTenant = await createTenant("importquota", "free");
    const limits = 100;

    for (let number = 1; number <= limits - 1; number += 1) {
      await issueService.createIssue(quotaTenant.actors.member, {
        orgId: quotaTenant.org.id,
        projectId: quotaTenant.project.id,
        title: `Seed ${number}`,
        description: null,
        status: "backlog",
        priority: "none",
        assigneeId: null,
        parentId: null,
        estimate: null,
        dueAt: null,
        labelIds: [],
      });
    }

    await expect(
      issueService.importIssues(quotaTenant.actors.member, {
        orgId: quotaTenant.org.id,
        projectId: quotaTenant.project.id,
        importKey: "quota-key",
        rows: [row(), row()],
      }),
    ).rejects.toThrow(/allows no more issues/);

    // Nothing created; key not consumed — retrying at a size that fits should work.
    const ok = await issueService.importIssues(quotaTenant.actors.member, {
      orgId: quotaTenant.org.id,
      projectId: quotaTenant.project.id,
      importKey: "quota-key",
      rows: [row()],
    });
    expect(ok.replayed).toBe(false);
    expect(ok.issues).toHaveLength(1);
  });

  it("refuses when the rate allowance does not cover the batch, and creates nothing", async () => {
    const rlTenant = await createTenant("importratelimit", "growth");
    resetRateLimits();

    await expect(
      issueService.importIssues(rlTenant.actors.member, {
        orgId: rlTenant.org.id,
        projectId: rlTenant.project.id,
        importKey: "rate-key",
        rows: Array.from({ length: 10_000 }, (_, i) => row({ title: `Row ${i}` })),
      }),
    ).rejects.toThrow(/rate limit/i);
  });

  it("records exactly one audit entry for the import, none per issue", async () => {
    const detach = registerActivityListeners();
    const auditTenant = await createTenant("importaudit", "growth");

    await issueService.importIssues(auditTenant.actors.member, {
      orgId: auditTenant.org.id,
      projectId: auditTenant.project.id,
      importKey: "audit-key",
      rows: [row(), row()],
    });

    const events = await activityRepo.listActivityForSubject(
      auditTenant.org.id,
      "project",
      auditTenant.project.id,
    );
    const importEvents = events.filter((e) => e.action === "issues.imported");
    expect(importEvents).toHaveLength(1);
    expect(importEvents[0]?.metadata).toMatchObject({ count: 2, importKey: "audit-key" });
    expect(importEvents[0]?.actorId).toBe(auditTenant.actors.member.userId);

    const issueCreatedEvents = events.filter((e) => e.action === "issue.created");
    expect(issueCreatedEvents).toHaveLength(0);

    detach();
  });

  it("agrees with a full usage recount after an import", async () => {
    const usageTenant = await createTenant("importusage", "growth");
    await issueService.importIssues(usageTenant.actors.member, {
      orgId: usageTenant.org.id,
      projectId: usageTenant.project.id,
      importKey: "usage-key",
      rows: [row(), row(), row()],
    });

    const recounted = await usageService.recomputeUsage(usageTenant.org.id);
    expect(recounted.issuesUsed).toBe(3);
  });
});

